def compute(vars):
    total_cost_of_revenues = vars["v1"] + vars["v2"]
    return {
        "value": total_cost_of_revenues,
        "trace": {
            "cost_of_revenues_2018": vars["v1"],
            "cost_of_revenues_2019": vars["v2"],
            "output_meta": {
                "currency": "USD",
                "scale": "thousand",
                "unit": None
            }
        }
    }
